const picked = $input.all().filter(item => {
  const status = String(item.json.Status ?? '').trim().toUpperCase();
  return status === 'APPROVED';
});

if (picked.length === 0) {
  throw new Error('No APPROVED candidate found.');
}

if (picked.length > 1) {
  throw new Error('More than one APPROVED candidate.');
}

return picked;

values.content:
=Create one original redesign direction for this user-selected candidate.

Product idea: {{$json.productIdea}}
Original title: {{$json.originalTitle}}
Opportunity score: {{$json.opportunityScore}}
Visible text: {{$json.visibleText}}
Reason: {{$json.reason}}
Safer alternative: {{$json.saferAlternative}}
Audience clues: infer from the product idea only.

The final image is intended for a print-on-demand shirt design. It should be centered, readable, print-ready, and isolated on a transparent background. Do not mention or recreate brands or protected characters.

parameters.jsCode:
const response = $json;
const b64 = response?.data?.[0]?.b64_json;
if (!b64) {
  throw new Error('OpenAI did not return data[0].b64_json');
}
const candidateId = $('Prepare Design Brief').item.json.candidateId;
return [{
  json: {
    ...$('Prepare Design Brief').item.json,
    imageCreated: true
  },
  binary: {
    design: {
      data: b64,
      mimeType: 'image/png',
      fileName: `pod-design-${candidateId}.png`,
      fileExtension: 'png'
    }
  }
}];

